import sys

def str_str_brute(haystack, needle):
    n, m = len(haystack), len(needle)
    for i in range(n - m + 1):
        for j in range(m):
            if haystack[i + j] != needle[j]:
                break
        else:
            return i
    return -1

if __name__ == '__main__':
    data = sys.stdin.read().splitlines()
    if len(data) < 2:
        sys.exit(0)
    print(str_str_brute(data[0].strip(), data[1].strip()))

