import sys

def build_next(p):
    n = len(p)
    nxt = [0] * n
    j = 0
    for i in range(1, n):
        while j > 0 and p[i] != p[j]:
            j = nxt[j - 1]
        if p[i] == p[j]:
            j += 1
        nxt[i] = j
    return nxt

def str_str_best(s, p):
    if not p:
        return 0
    n, m = len(s), len(p)
    nxt = build_next(p)
    j = 0
    for i in range(n):
        while j > 0 and s[i] != p[j]:
            j = nxt[j - 1]
        if s[i] == p[j]:
            j += 1
        if j == m:
            return i - m + 1
    return -1

if __name__ == '__main__':
    data = sys.stdin.read().splitlines()
    if len(data) < 2:
        sys.exit(0)
    print(str_str_best(data[0].strip(), data[1].strip()))
